-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.board_token(p_world uuid, p_uid uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object('x', d.x, 'y', d.y, 'deed', d.name)
    from deed d join player p on p.world_id = d.world_id and p.uid = p_uid
   where d.world_id = p_world
   order by (d.x + 0.5 - p.x) ^ 2 + (d.y + 0.5 - p.y) ^ 2, d.x, d.y
   limit 1
$function$
